def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    m = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}

    children = [[-1] * m]
    terminal = [False]

    for pattern in banned:
        state = 0
        for ch in pattern:
            c = char_index[ch]
            if children[state][c] == -1:
                children[state][c] = len(children)
                children.append([-1] * m)
                terminal.append(False)
            state = children[state][c]
        terminal[state] = True

    failure = [0] * len(children)
    queue = []

    for c in range(m):
        nxt = children[0][c]
        if nxt == -1:
            children[0][c] = 0
        else:
            queue.append(nxt)

    head = 0
    while head < len(queue):
        state = queue[head]
        head += 1
        terminal[state] |= terminal[failure[state]]

        for c in range(m):
            nxt = children[state][c]
            if nxt == -1:
                children[state][c] = children[failure[state]][c]
            else:
                failure[nxt] = children[failure[state]][c]
                queue.append(nxt)

    safe_states = [i for i in range(len(children)) if not terminal[i]]
    index = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for state in safe_states:
        row = matrix[index[state]]
        for nxt in children[state]:
            if not terminal[nxt]:
                row[index[nxt]] += 1

    vector = [0] * size
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * size
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        result[j] += value * weight
            vector = [value % MOD for value in result]

        n >>= 1
        if n:
            squared = [[0] * size for _ in range(size)]
            for i in range(size):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, weight in enumerate(matrix[k]):
                            squared[i][j] += value * weight
                squared[i] = [value % MOD for value in squared[i]]
            matrix = squared

    return sum(vector) % MOD
